css:
@import url('https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&display=swap');

:root {
  --bg: #1b1630;
  --bg2: #261f40;
  --bg3: #322a52;
  --paper: #fffaf0;
  --paper2: #f3e8cf;
  --ink: #2b2235;
  --muted: #8f87ad;
  --soft: #c9c1e3;
  --gold: #f2c14e;
  --gold2: #ffd76e;
  --red: #e5534b;
  --green: #4fae5a;
  --blue: #4f72bf;
  --purple: #7b5fc7;
  --font: 'Fredoka', 'Segoe UI Variable Display', 'Segoe UI', system-ui, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  background: var(--bg);
  color: var(--paper);
  font-family: var(--font);
  font-size: 15px;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}
input, textarea, select { font-family: var(--font); user-select: text; }
.hidden { display: none !important; }

.paper {
  background: var(--paper);
  color: var(--ink);
  border: 3px solid var(--ink);
  border-radius: 16px;
  box-shadow: 0 0 0 4px var(--paper), 0 8px 0 4px rgba(0, 0, 0, 0.28);
}

.btn {
  font-family: var(--font);
  font-weight: 600;
  font-size: 15px;
  color: var(--ink);
  background: var(--paper);
  border: 3px solid var(--ink);
  border-radius: 12px;
  padding: 7px 14px;
  cursor: pointer;
  box-shadow: 0 4px 0 var(--ink);
  transform: translateY(0);
  transition: transform 0.06s, box-shadow 0.06s, filter 0.1s;
  white-space: nowrap;
}
.btn:hover { filter: brightness(1.06); }
.btn:active, .btn.pressed { transform: translateY(3px); box-shadow: 0 1px 0 var(--ink); }
.btn:focus-visible { outline: 3px solid var(--gold2); outline-offset: 3px; }
.btn:disabled { opacity: 0.45; cursor: default; transform: none; box-shadow: 0 4px 0 var(--ink); }
.btn.gold { background: linear-gradient(#ffe27a, #f2b43a); }
.btn.green { background: linear-gradient(#8be07a, #4fae5a); }
.btn.red { background: linear-gradient(#ff8a7a, #e5534b); color: #fff; text-shadow: 0 1px 0 rgba(0,0,0,0.3); }
.btn.blue { background: linear-gradient(#8fb0ff, #4f72bf); color: #fff; text-shadow: 0 1px 0 rgba(0,0,0,0.3); }
.btn.purple { background: linear-gradient(#b49cff, #7b5fc7); color: #fff; text-shadow: 0 1px 0 rgba(0,0,0,0.3); }
.btn.ghost { background: transparent; color: var(--paper); border-color: var(--soft); box-shadow: 0 4px 0 rgba(0,0,0,0.35); }
.btn.small { font-size: 13px; padding: 4px 10px; border-radius: 10px; box-shadow: 0 3px 0 var(--ink); }
.btn.big { font-size: 18px; padding: 10px 20px; }

.chip {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--bg3); border: 2px solid rgba(255,255,255,0.12);
  border-radius: 999px; padding: 4px 12px; font-weight: 600;
}
.chip.light { color: var(--gold2); }

.bar { height: 10px; background: rgba(0,0,0,0.25); border-radius: 99px; overflow: hidden; border: 2px solid var(--ink); }
.bar > i { display: block; height: 100%; background: linear-gradient(90deg, #ffd25e, #ff9a3d); border-radius: 99px; }

::-webkit-scrollbar { width: 10px; }
::-webkit-scrollbar-thumb { background: var(--bg3); border-radius: 10px; }

body {
  display: flex; flex-direction: column; height: 100vh; overflow: hidden;
  background:
    radial-gradient(1200px 500px at 80% -10%, rgba(242, 193, 78, 0.12), transparent 60%),
    radial-gradient(900px 500px at -10% 110%, rgba(123, 95, 199, 0.25), transparent 60%),
    var(--bg);
}
.top {
  display: flex; align-items: center; gap: 18px; padding: 10px 18px;
  background: rgba(0, 0, 0, 0.25); border-bottom: 2px solid rgba(255, 255, 255, 0.07);
}
.logo { font-size: 22px; font-weight: 700; white-space: nowrap; }
.logo span { color: var(--gold2); letter-spacing: 0.5px; }
#tabs { display: flex; gap: 6px; flex: 1; }
#tabs button {
  font-family: var(--font); font-size: 15px; font-weight: 600; color: var(--soft);
  background: transparent; border: 2px solid transparent; border-radius: 12px; padding: 7px 14px; cursor: pointer;
}
#tabs button:hover { background: rgba(255, 255, 255, 0.06); color: var(--paper); }
#tabs button.active { background: var(--paper); color: var(--ink); border-color: var(--ink); box-shadow: 0 3px 0 var(--ink); }
.wallet { display: flex; gap: 8px; }

.session-bar {
  display: flex; align-items: center; gap: 12px; padding: 8px 18px; font-weight: 600;
  background: linear-gradient(90deg, #3d2f6e, #2a2148); border-bottom: 2px solid rgba(255, 255, 255, 0.08);
}
.session-bar.break { background: linear-gradient(90deg, #2f5a3a, #1f3a2a); }
.session-bar.alert { background: linear-gradient(90deg, #6e2f3a, #3a1f2a); }
.session-bar .grow { flex: 1; }
.session-bar .dot { width: 10px; height: 10px; border-radius: 50%; background: #8be07a; box-shadow: 0 0 10px #8be07a; }
.session-bar.alert .dot { background: #ff7a6e; box-shadow: 0 0 10px #ff7a6e; }
.update-bar {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap; padding: 8px 18px; font-size: 14px;
  background: linear-gradient(90deg, #6b4f1d, #3d2f15); border-bottom: 2px solid rgba(255, 255, 255, 0.08);
}
.update-bar .grow { flex: 1; }
.update-bar .muted { color: #e6d6ae; font-size: 13px; }

main { flex: 1; overflow: hidden; position: relative; }
.tab { position: absolute; inset: 0; overflow-y: auto; padding: 20px 24px 40px; display: none; }
.tab.active { display: block; }
#tab-adventure { padding: 12px; overflow: hidden; }
#tab-adventure.active { display: flex; align-items: center; justify-content: center; }

.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(330px, 1fr)); gap: 22px; align-items: start; max-width: 1200px; margin: 0 auto; }
.card { padding: 18px 20px; }
.card h2 { margin: 0 0 10px; font-size: 21px; }
.card h3 { margin: 14px 0 6px; font-size: 16px; color: #5d4f80; }
.card p { margin: 6px 0; line-height: 1.4; }
.muted { color: #7a7192; }
.card .muted { color: #7a7192; }
.span2 { grid-column: span 2; }
@media (max-width: 760px) { .span2 { grid-column: auto; } }

.start-card { background: linear-gradient(160deg, #fffaf0 60%, #ffeec4); }
.start-card select {
  width: 100%; font-size: 16px; padding: 9px 12px; border-radius: 12px; border: 3px solid var(--ink);
  background: #fff; color: var(--ink); font-weight: 500;
}
.check { display: flex; gap: 10px; align-items: flex-start; margin: 10px 0; cursor: pointer; line-height: 1.3; }
.check input { width: 20px; height: 20px; accent-color: var(--purple); margin-top: 1px; flex: none; }
.next-step { margin: 10px 0 4px; padding: 9px 12px; border-radius: 12px; background: #f1e6ff; border: 2px dashed #b49cff; }

.task { display: grid; grid-template-columns: 1fr auto; gap: 6px 12px; align-items: center; padding: 10px 0; border-bottom: 2px dashed #e4d8bd; }
.task:last-child { border-bottom: 0; }
.task .bar { grid-column: 1; }
.task .reward { font-size: 13px; color: #7a7192; }
.task.done .title { text-decoration: line-through; color: #7a7192; }

.streak-big { font-size: 46px; font-weight: 700; color: #e8722a; line-height: 1; }
.milestones { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 10px; }
.milestone { padding: 6px 10px; border-radius: 10px; border: 2px solid #e4d8bd; font-size: 13px; font-weight: 600; }
.milestone.ready { border-color: var(--gold); background: #fff3c9; }
.milestone.claimed { opacity: 0.5; }

.stat-row { display: flex; gap: 10px; flex-wrap: wrap; }
.stat { flex: 1; min-width: 90px; padding: 10px; border-radius: 12px; background: #f6efdd; text-align: center; }
.stat b { display: block; font-size: 22px; }
.log { margin-top: 10px; font-size: 14px; }
.log div { padding: 5px 0; border-bottom: 1px solid #eadfc6; }

/* the start menu: the title screen Lantern Delve opens on */
.start {
  position: fixed; inset: 0; z-index: 40; display: flex; align-items: center; justify-content: center; overflow-y: auto;
  background:
    radial-gradient(2px 2px at 12% 18%, rgba(255, 255, 255, 0.8), transparent 60%),
    radial-gradient(2px 2px at 28% 8%, rgba(255, 255, 255, 0.6), transparent 60%),
    radial-gradient(2px 2px at 70% 14%, rgba(255, 255, 255, 0.7), transparent 60%),
    radial-gradient(2px 2px at 86% 26%, rgba(255, 255, 255, 0.6), transparent 60%),
    radial-gradient(1.5px 1.5px at 52% 6%, rgba(255, 255, 255, 0.7), transparent 60%),
    radial-gradient(1.5px 1.5px at 92% 8%, rgba(255, 255, 255, 0.5), transparent 60%),
    radial-gradient(1.5px 1.5px at 6% 40%, rgba(255, 255, 255, 0.5), transparent 60%),
    radial-gradient(900px 520px at 50% 30%, rgba(255, 196, 90, 0.16), transparent 60%),
    linear-gradient(180deg, #120c2a 0%, #241a4a 58%, #33275a 100%);
  transition: opacity 0.35s;
}
.start.hide { opacity: 0; pointer-events: none; }
.start-inner { text-align: center; padding: 20px 16px 28px; width: 100%; max-width: 760px; }
.start canvas { display: block; width: min(560px, 92vw); height: auto; margin: 0 auto -6px; }
.start-title {
  margin: 0; font-size: 62px; line-height: 1.05; color: var(--paper); letter-spacing: 1px;
  text-shadow: 0 4px 0 var(--ink), 0 0 34px rgba(255, 200, 100, 0.45);
}
.start-title span { color: var(--gold2); }
.start-sub { margin: 4px 0 0; color: var(--soft); font-size: 17px; letter-spacing: 0.5px; }
.start-hi { margin: 12px 0 18px; color: var(--paper); font-size: 18px; }
.start-btns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; max-width: 560px; margin: 0 auto; }
.sbtn {
  display: flex; flex-direction: column; align-items: center; gap: 1px; padding: 12px 14px 13px; cursor: pointer;
  font-family: var(--font); color: var(--paper); background: var(--bg2);
  border: 3px solid rgba(255, 255, 255, 0.14); border-radius: 16px; box-shadow: 0 5px 0 rgba(0, 0, 0, 0.4);
  transition: transform 0.12s, border-color 0.12s;
}
.sbtn .i { font-size: 28px; line-height: 1.1; }
.sbtn b { font-size: 19px; }
.sbtn small { font-size: 13px; color: var(--soft); }
.sbtn:hover, .sbtn:focus-visible { transform: translateY(-3px); border-color: var(--gold2); outline: none; }
.sbtn:active { transform: translateY(1px); box-shadow: 0 2px 0 rgba(0, 0, 0, 0.4); }
.sbtn.primary { background: var(--paper); color: var(--ink); border-color: var(--ink); box-shadow: 0 5px 0 var(--ink); }
.sbtn.primary small { color: #7a7192; }
.start-stats { margin: 18px 0 0; color: var(--soft); font-size: 15px; min-height: 1.3em; }
.start-keys { margin: 6px 0 0; color: rgba(255, 255, 255, 0.38); font-size: 12px; }
@media (max-width: 520px) { .start-btns { grid-template-columns: 1fr; } .start-title { font-size: 44px; } }

/* homework */
.hw { display: grid; grid-template-columns: 340px 1fr; gap: 22px; max-width: 1200px; margin: 0 auto; height: 100%; }
.hw-list { display: flex; flex-direction: column; gap: 10px; }
.quest-item { padding: 12px 14px; border-radius: 14px; background: var(--bg2); border: 2px solid rgba(255, 255, 255, 0.08); cursor: pointer; }
.quest-item:hover { border-color: rgba(255, 255, 255, 0.25); }
.quest-item.sel { background: var(--paper); color: var(--ink); border-color: var(--ink); box-shadow: 0 4px 0 var(--ink); }
.quest-item.done { opacity: 0.55; }
.quest-item .t { font-weight: 600; font-size: 16px; }
.quest-item .m { font-size: 13px; color: var(--muted); margin-top: 3px; }
.quest-item.sel .m { color: #7a7192; }
.quest-item .bar { margin-top: 8px; height: 8px; }
/* the Completed folder: a paper folder tab under the list, holding finished assignments */
.done-folder { margin-top: 6px; border-radius: 14px; }
.done-folder .folder-tab {
  display: flex; align-items: center; gap: 9px; width: 100%; padding: 10px 14px; cursor: pointer; text-align: left;
  font-family: var(--font); font-size: 15px; font-weight: 600; color: var(--paper);
  background: linear-gradient(180deg, #8a6a2e, #6b4f1d); border: 2px solid rgba(0, 0, 0, 0.35); border-radius: 12px 12px 12px 12px;
  box-shadow: 0 3px 0 rgba(0, 0, 0, 0.35);
}
.done-folder .folder-tab:hover { filter: brightness(1.12); }
.done-folder.open .folder-tab { border-radius: 12px 12px 0 0; box-shadow: none; }
.done-folder .ico { font-size: 19px; }
.done-folder .name { flex: 1; }
.done-folder .count { min-width: 26px; padding: 1px 8px; border-radius: 10px; background: rgba(0, 0, 0, 0.3); text-align: center; font-size: 13px; }
.done-folder .arrow { font-size: 14px; opacity: 0.8; }
.done-folder .folder-body {
  display: flex; flex-direction: column; gap: 8px; padding: 10px;
  background: rgba(107, 79, 29, 0.28); border: 2px solid rgba(0, 0, 0, 0.35); border-top: 0; border-radius: 0 0 12px 12px;
}
.done-folder .folder-body .quest-item { padding: 9px 12px; }
.done-folder .folder-body .quest-item .t { font-size: 15px; }
.all-done { padding: 12px 14px; border-radius: 14px; border: 2px dashed rgba(255, 255, 255, 0.18); color: var(--soft); font-size: 14px; line-height: 1.4; }

/* due dates: the list's groups (Overdue, Due today... No due date) and the little due label on each assignment */
.due-group { display: flex; flex-direction: column; gap: 8px; }
.due-group + .due-group { margin-top: 6px; }
.due-head { display: flex; align-items: center; gap: 8px; padding: 2px 4px 0; font-size: 13.5px; font-weight: 700; color: var(--soft); }
.due-head .count { min-width: 22px; padding: 0 7px; border-radius: 9px; background: rgba(255, 255, 255, 0.1); text-align: center; font-size: 12px; }
.g-overdue .due-head { color: #ff9a8f; }
.g-today .due-head { color: var(--gold2); }
.g-old .due-head { color: #c9b6ff; }
.quest-item .m { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.due-chip { display: inline-flex; align-items: center; gap: 4px; padding: 1px 8px; border-radius: 9px; font-size: 12.5px; font-weight: 600;
  white-space: nowrap; background: rgba(255, 255, 255, 0.08); color: var(--soft); border: 1.5px solid rgba(255, 255, 255, 0.14); }
.due-chip.over { background: #5a2330; color: #ffb3aa; border-color: #a8444c; }
.due-chip.today { background: #5a4520; color: #ffe08a; border-color: #a8873a; }
.due-chip.tomorrow { background: #3d3560; color: #e3d8ff; border-color: #6e5fb0; }
.due-chip.old { background: transparent; border-style: dashed; color: #c9b6ff; }
/* (on paper: a picked assignment, the Today tab) */
.quest-item.sel .due-chip, .paper .due-chip { background: #f3ecdc; color: var(--ink); border-color: #d9ccb0; }
.quest-item.sel .due-chip.over, .paper .due-chip.over { background: #fde3df; color: #a3271d; border-color: #e5948b; }
.quest-item.sel .due-chip.today, .paper .due-chip.today { background: #fff0c2; color: #7a5600; border-color: #e6c36a; }
.quest-item.sel .due-chip.tomorrow, .paper .due-chip.tomorrow { background: #ece6ff; color: #4a3a8f; border-color: #c2b4f0; }
.quest-item.sel .due-chip.old, .paper .due-chip.old { background: transparent; color: #5d4f80; border-color: #b49cff; }
/* the due date on an assignment's page, with its one-click fixes */
.due-box { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin: 10px 0 2px; padding: 9px 12px; border-radius: 12px;
  background: #f6efdd; border: 2px solid #e4d8bd; line-height: 1.35; }
.due-box .grow { flex: 1; }
.due-box.over { background: #fde8e5; border-color: #eaa49c; color: #8f2219; }
.due-box.today { background: #fff3c9; border-color: #ecc95f; }
.due-box.tomorrow { background: #f1ebff; border-color: #c7b8f2; }
.due-box.old { flex-direction: column; align-items: stretch; background: #f1ebff; border: 2px dashed #b49cff; }
.due-box.none { color: #7a7192; }
/* the due date picker */
.due-pick { padding: 10px 12px; border-radius: 12px; background: #faf6ec; border: 2px solid #e4d8bd; margin-bottom: 6px; }
.dchips { display: flex; flex-wrap: wrap; gap: 6px; }
.dchip { font-family: var(--font); font-size: 14px; font-weight: 600; padding: 5px 11px; border-radius: 999px; cursor: pointer;
  background: #fff; color: var(--ink); border: 2px solid #cfc3a8; }
.dchip:hover { border-color: var(--ink); }
.dchip.on { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.drow { display: flex; align-items: center; gap: 8px; margin-top: 10px; flex-wrap: wrap; }
.drow input { font-family: var(--font); font-size: 15px; padding: 6px 10px; border-radius: 10px; border: 3px solid var(--ink); background: #fff; color: var(--ink); }
.drow .at { color: #7a7192; font-weight: 600; }
.due-pick.empty .dp-time, .due-pick.empty .at { opacity: 0.45; }
.dp-prev { margin-top: 8px; font-size: 14px; }
.dp-prev.over { color: #a3271d; }
.dp-prev.none { color: #7a7192; }
.dp-note { margin-top: 6px; font-size: 13px; color: #5d4f80; padding: 6px 9px; border-radius: 9px; background: #f1ebff; }
/* 📌 Coming up, on the Today tab */
.coming .due-row { display: flex; align-items: center; gap: 10px; padding: 8px 10px; margin: 0 -6px; border-radius: 11px; cursor: pointer;
  border: 2px solid transparent; }
.coming .due-row:hover { background: #f6efdd; }
.coming .due-row.sel { background: #fff3c9; border-color: #ecc95f; }
.coming .due-row .t { flex: 1; min-width: 0; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.coming .due-row .n { font-size: 13px; color: #7a7192; }
.coming .more { font-size: 13px; margin-top: 10px; }
.linkish { font-family: var(--font); font-size: 13px; font-weight: 700; background: none; border: none; padding: 0; margin-right: 6px;
  color: var(--purple); cursor: pointer; text-decoration: underline; }
.steps { list-style: none; padding: 0; margin: 10px 0; }
.steps li { display: flex; gap: 10px; align-items: flex-start; padding: 7px 4px; border-bottom: 1px dashed #e4d8bd; cursor: pointer; line-height: 1.3; }
.steps li.done span { text-decoration: line-through; color: #9a91b0; }
.steps li.next { background: #fff3c9; border-radius: 8px; }
.steps input { width: 18px; height: 18px; accent-color: var(--green); flex: none; margin-top: 1px; }
.empty { text-align: center; padding: 50px 20px; color: var(--soft); font-size: 17px; line-height: 1.5; }

/* forms */
.field { margin: 10px 0; }
.field label { display: block; font-weight: 600; margin-bottom: 5px; }
.field input[type=text], .field input[type=number], .field textarea, .field select {
  width: 100%; font-size: 15px; padding: 8px 11px; border-radius: 11px; border: 3px solid var(--ink); background: #fff; color: var(--ink);
}
.field input[type=number] { width: 100px; }
.field input[type=range] { width: 100%; accent-color: var(--purple); cursor: pointer; }
.field textarea { resize: vertical; line-height: 1.35; }
.field .hint { font-size: 13px; color: #7a7192; margin-top: 4px; }
.row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.row.end { justify-content: flex-end; }
.spacer { flex: 1; }

/* homework files */
.files { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 8px 0 2px; }
.files:empty { display: none; }
.file { display: inline-flex; align-items: center; gap: 6px; max-width: 100%; padding: 4px 4px 4px 10px; border-radius: 10px;
  border: 2px solid var(--ink); background: #fff; color: var(--ink); font-size: 14px; box-shadow: 0 2px 0 var(--ink); }
.file .fname { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 280px; }
.file .fname[data-a] { cursor: pointer; }
.file .fname[data-a]:hover { text-decoration: underline; }
.file .fsize { font-size: 12px; color: #7a7192; white-space: nowrap; }
.file.up { opacity: 0.7; border-style: dashed; }
.file.err { border-color: var(--red); }
.file.err .fsize { color: var(--red); }
.file .x { border: none; background: none; font-size: 17px; line-height: 1; padding: 1px 6px; cursor: pointer; color: #7a7192; border-radius: 6px; }
.file .x:hover { color: var(--red); background: #fde8e6; }
.drop { border: 3px dashed #b9add6; border-radius: 12px; padding: 14px; text-align: center; cursor: pointer; background: #faf6ec; color: var(--ink); }
.drop:hover, .drop.over { border-color: var(--purple); background: #f1ebff; }

.ai-status { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 12px; background: #f6efdd; margin: 8px 0; }
.ai-status .dot { width: 12px; height: 12px; border-radius: 50%; flex: none; background: #c9c1e3; }
.ai-status.ready .dot { background: var(--green); box-shadow: 0 0 8px var(--green); }
.ai-status.not_logged_in .dot, .ai-status.error .dot { background: var(--gold); }
.ai-status.missing .dot { background: var(--red); }

/* modal + toast */
.modal { position: fixed; inset: 0; background: rgba(10, 6, 20, 0.6); display: grid; place-items: center; z-index: 50; padding: 20px; }
.modal-card { width: min(640px, 100%); max-height: 90vh; overflow-y: auto; padding: 22px 24px; }
.modal-card h2 { margin: 0 0 8px; }
.summary-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 14px 0; }
.toast {
  position: fixed; left: 50%; bottom: 28px; transform: translateX(-50%); z-index: 60;
  background: var(--paper); color: var(--ink); border: 3px solid var(--ink); border-radius: 14px; padding: 10px 18px;
  font-weight: 600; box-shadow: 0 6px 0 rgba(0, 0, 0, 0.3); animation: pop 0.25s ease-out;
}
@keyframes pop { from { transform: translate(-50%, 20px) scale(0.9); opacity: 0; } to { transform: translate(-50%, 0) scale(1); opacity: 1; } }

.game-root { width: 100%; height: 100%; container-type: size; display: flex; align-items: center; justify-content: center; }
.game {
  position: relative; width: min(100cqw, 100cqh * 16 / 9); aspect-ratio: 16 / 9; container-type: inline-size;
  border: 4px solid var(--ink); border-radius: 18px; overflow: hidden; background: #120e22;
  box-shadow: 0 0 0 5px var(--paper), 0 12px 0 5px rgba(0, 0, 0, 0.35);
  font-size: clamp(11px, 1.45cqw, 18px);
}
.g-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

/* HUD */
.g-hud { position: absolute; top: 0; left: 0; right: 0; display: flex; justify-content: space-between; align-items: flex-start; gap: 0.6em; padding: 0.7em; pointer-events: none; }
.hud-left, .hud-right { display: flex; gap: 0.4em; flex-wrap: wrap; }
.hud-right { justify-content: flex-end; }
.hud-pill {
  background: var(--paper); color: var(--ink); border: 2px solid var(--ink); border-radius: 999px; padding: 0.15em 0.7em;
  font-weight: 700; box-shadow: 0 3px 0 rgba(0, 0, 0, 0.3); white-space: nowrap;
}
.hud-pill.hp { color: #c73a52; }
.hud-pill.fp { color: #2f6db5; }
.hud-pill.light { background: linear-gradient(#fff3c4, #ffd56b); }
.hud-pill.light small { font-weight: 500; opacity: 0.75; }
.hud-pill.break { background: #d6f5d9; }
.hud-pill.chest { background: linear-gradient(#ffe6f0, #ffc2d6); animation: bob 1.2s infinite; }
.hud-obj {
  flex: 1; text-align: center; color: #fffaf0; font-weight: 600; text-shadow: 0 2px 0 rgba(0, 0, 0, 0.6), 0 0 8px rgba(0, 0, 0, 0.5);
  padding-top: 0.2em; font-size: 0.95em;
}

/* dialogue */
.g-dialog {
  position: absolute; left: 3%; right: 3%; bottom: 4%; display: flex; gap: 0.8em; align-items: flex-end;
  background: var(--paper); color: var(--ink); border: 3px solid var(--ink); border-radius: 18px;
  box-shadow: 0 0 0 4px var(--paper), 0 8px 0 4px rgba(0, 0, 0, 0.3); padding: 0.8em 1.2em; min-height: 21%; cursor: pointer;
  animation: dlgin 0.18s ease-out;
}
@keyframes dlgin { from { transform: translateY(12px); opacity: 0; } to { transform: none; opacity: 1; } }
.g-dialog .portrait { width: 14cqw; height: 14cqw; margin-top: -7cqw; flex: none; }
.dlg-body { flex: 1; position: relative; align-self: stretch; }
.dlg-name { display: inline-block; background: var(--purple); color: #fff; border-radius: 10px; padding: 0.05em 0.8em; font-weight: 700; margin-bottom: 0.3em; }
.dlg-text { font-size: 1.22em; line-height: 1.35; font-weight: 500; min-height: 2.7em; }
.dlg-next { position: absolute; right: 0; bottom: -0.2em; font-size: 1.1em; animation: bob 0.8s infinite; color: var(--purple); }
@keyframes bob { 50% { transform: translateY(4px); } }
.g-dialog.narrate { justify-content: center; text-align: center; background: #2a2148; color: #fffaf0; border-color: #fffaf0; box-shadow: 0 0 0 4px #2a2148, 0 8px 0 4px rgba(0, 0, 0, 0.3); }
.g-dialog.narrate .dlg-name { display: none; }
.g-dialog.narrate .dlg-text { font-style: italic; }
.g-dialog.narrate .dlg-next { color: var(--gold2); }

/* menus */
.g-panel { position: absolute; top: 9%; right: 3%; width: 44%; max-height: 86%; overflow-y: auto; }
.g-battle .bmenu { position: absolute; left: 3%; bottom: 4%; width: 36%; }
.menu {
  background: var(--paper); color: var(--ink); border: 3px solid var(--ink); border-radius: 16px; padding: 0.7em;
  box-shadow: 0 0 0 4px var(--paper), 0 8px 0 4px rgba(0, 0, 0, 0.3); animation: dlgin 0.15s ease-out;
}
.menu-title { font-weight: 700; font-size: 1.2em; padding: 0.1em 0.4em 0.4em; border-bottom: 2px dashed #e4d8bd; margin-bottom: 0.4em; }
.menu-info { font-size: 0.92em; color: #6b5a8a; padding: 0 0.4em 0.5em; line-height: 1.3; }
.menu-items { display: flex; flex-direction: column; gap: 0.15em; }
.mi {
  display: flex; justify-content: space-between; align-items: center; gap: 1em; width: 100%; text-align: left;
  font: inherit; font-weight: 600; padding: 0.4em 0.7em; border-radius: 10px; border: 2px solid transparent;
  background: transparent; color: var(--ink); cursor: pointer;
}
.mi.sel { background: #fff3c9; border-color: var(--ink); }
.mi.sel .ml::before { content: '▶ '; color: var(--purple); }
.mi.dis { opacity: 0.4; cursor: default; }
.mi .mr { font-weight: 500; color: #6b5a8a; white-space: nowrap; }
.menu-desc { min-height: 1.3em; font-size: 0.9em; color: #4a3f5e; padding: 0.5em 0.4em 0.1em; line-height: 1.3; }
.menu-desc:empty { display: none; }
.menu-keys { font-size: 0.75em; color: #9a8fb3; padding: 0.4em 0.4em 0; }
.menu.battle { font-size: 1.05em; }

/* cards, tips, lock */
.g-card { position: absolute; inset: 0; display: grid; place-items: center; pointer-events: none; }
.card-in {
  background: var(--paper); color: var(--ink); border: 4px solid var(--ink); border-radius: 22px; padding: 0.8em 2.2em; text-align: center;
  box-shadow: 0 0 0 6px var(--paper), 0 12px 0 6px rgba(0, 0, 0, 0.35); animation: cardpop 0.45s cubic-bezier(.2, 1.6, .4, 1);
}
@keyframes cardpop { from { transform: scale(0.4) rotate(-6deg); opacity: 0; } to { transform: none; opacity: 1; } }
.card-title { font-size: 2.6em; font-weight: 700; }
.card-sub { font-size: 1.2em; color: #6b5a8a; margin-top: 0.2em; }
.g-tip {
  position: absolute; left: 50%; bottom: 28%; transform: translateX(-50%); max-width: 80%; text-align: center;
  background: rgba(20, 12, 40, 0.88); color: #fffaf0; border: 2px solid rgba(255, 255, 255, 0.25); border-radius: 12px;
  padding: 0.45em 1.1em; font-weight: 600; pointer-events: none; animation: dlgin 0.2s ease-out;
}
.g-lock { position: absolute; inset: 0; background: rgba(15, 10, 30, 0.84); display: grid; place-items: center; backdrop-filter: blur(3px); }
.lock-card {
  background: var(--paper); color: var(--ink); border: 3px solid var(--ink); border-radius: 18px; padding: 1.2em 2em; text-align: center; max-width: 60%;
  box-shadow: 0 0 0 4px var(--paper), 0 10px 0 4px rgba(0, 0, 0, 0.35);
}
.lock-card h2 { margin: 0.2em 0; }
.lock-card p { margin: 0.4em 0 0.8em; line-height: 1.35; }
.lock-big { font-size: 3em; }
.g-help {
  position: absolute; bottom: 0.4em; left: 50%; transform: translateX(-50%); font-size: 0.8em; white-space: nowrap;
  color: rgba(255, 250, 240, 0.75); text-shadow: 0 1px 2px #000; pointer-events: none;
}
.g-dialog:not(.hidden) ~ .g-help, .g-battle:not(.hidden) ~ .g-help { display: none; }

buddy_css:
@import url('https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&display=swap');

:root {
  --bg: #1b1630;
  --bg2: #261f40;
  --bg3: #322a52;
  --paper: #fffaf0;
  --paper2: #f3e8cf;
  --ink: #2b2235;
  --muted: #8f87ad;
  --soft: #c9c1e3;
  --gold: #f2c14e;
  --gold2: #ffd76e;
  --red: #e5534b;
  --green: #4fae5a;
  --blue: #4f72bf;
  --purple: #7b5fc7;
  --font: 'Fredoka', 'Segoe UI Variable Display', 'Segoe UI', system-ui, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  background: var(--bg);
  color: var(--paper);
  font-family: var(--font);
  font-size: 15px;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}
input, textarea, select { font-family: var(--font); user-select: text; }
.hidden { display: none !important; }

.paper {
  background: var(--paper);
  color: var(--ink);
  border: 3px solid var(--ink);
  border-radius: 16px;
  box-shadow: 0 0 0 4px var(--paper), 0 8px 0 4px rgba(0, 0, 0, 0.28);
}

.btn {
  font-family: var(--font);
  font-weight: 600;
  font-size: 15px;
  color: var(--ink);
  background: var(--paper);
  border: 3px solid var(--ink);
  border-radius: 12px;
  padding: 7px 14px;
  cursor: pointer;
  box-shadow: 0 4px 0 var(--ink);
  transform: translateY(0);
  transition: transform 0.06s, box-shadow 0.06s, filter 0.1s;
  white-space: nowrap;
}
.btn:hover { filter: brightness(1.06); }
.btn:active, .btn.pressed { transform: translateY(3px); box-shadow: 0 1px 0 var(--ink); }
.btn:focus-visible { outline: 3px solid var(--gold2); outline-offset: 3px; }
.btn:disabled { opacity: 0.45; cursor: default; transform: none; box-shadow: 0 4px 0 var(--ink); }
.btn.gold { background: linear-gradient(#ffe27a, #f2b43a); }
.btn.green { background: linear-gradient(#8be07a, #4fae5a); }
.btn.red { background: linear-gradient(#ff8a7a, #e5534b); color: #fff; text-shadow: 0 1px 0 rgba(0,0,0,0.3); }
.btn.blue { background: linear-gradient(#8fb0ff, #4f72bf); color: #fff; text-shadow: 0 1px 0 rgba(0,0,0,0.3); }
.btn.purple { background: linear-gradient(#b49cff, #7b5fc7); color: #fff; text-shadow: 0 1px 0 rgba(0,0,0,0.3); }
.btn.ghost { background: transparent; color: var(--paper); border-color: var(--soft); box-shadow: 0 4px 0 rgba(0,0,0,0.35); }
.btn.small { font-size: 13px; padding: 4px 10px; border-radius: 10px; box-shadow: 0 3px 0 var(--ink); }
.btn.big { font-size: 18px; padding: 10px 20px; }

.chip {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--bg3); border: 2px solid rgba(255,255,255,0.12);
  border-radius: 999px; padding: 4px 12px; font-weight: 600;
}
.chip.light { color: var(--gold2); }

.bar { height: 10px; background: rgba(0,0,0,0.25); border-radius: 99px; overflow: hidden; border: 2px solid var(--ink); }
.bar > i { display: block; height: 100%; background: linear-gradient(90deg, #ffd25e, #ff9a3d); border-radius: 99px; }

::-webkit-scrollbar { width: 10px; }
::-webkit-scrollbar-thumb { background: var(--bg3); border-radius: 10px; }

body { overflow: hidden; background: linear-gradient(#231c3d, #1b1630); }
#app { display: flex; flex-direction: column; height: 100vh; padding: 0 0 6px; }
/* the little scene takes whatever room the panel leaves (and steps aside when there's almost none);
   companion.js zooms the panel so its text and buttons always fit the window */
#scene { width: 100%; flex: 1 1 0; min-height: 0; display: block; }
#scene.gone { display: none; }
#panel { flex: none; overflow-wrap: anywhere; }

.stats {
  display: flex; justify-content: space-between; align-items: center; gap: 2px 6px; flex-wrap: wrap;
  padding: 6px 10px 0; font-weight: 600; font-size: 14px;
}
.stats .light { color: var(--gold2); }
.stats .lost { color: #ff9a8f; }
.bondline { padding: 3px 10px 0; font-size: 12.5px; color: #ffc2d6; font-weight: 600; }
.dueline { padding: 5px 10px 0; font-size: 12.5px; font-weight: 600; color: var(--soft); }
.dueline.over { color: #ff9a8f; }
.dueline.today { color: var(--gold2); }
.step {
  margin: 8px 10px 0; padding: 7px 11px; font-size: 14px; line-height: 1.25; border-radius: 12px;
  box-shadow: 0 0 0 3px var(--paper), 0 5px 0 3px rgba(0,0,0,0.28);
}
.step b { color: var(--purple); }
.speech {
  position: relative; margin: 12px 10px 0; padding: 7px 11px; font-size: 13.5px; line-height: 1.3;
  background: var(--bg3); border: 2px solid rgba(255,255,255,0.15); border-radius: 12px; min-height: 36px;
}
.speech::before {
  content: ''; position: absolute; top: -9px; left: 26px; border: 8px solid transparent;
  border-bottom-color: rgba(255,255,255,0.15); border-top: 0;
}
.speech.mood-angry { border-color: #ff7a6e; background: #4a2234; }
.speech.mood-worried { border-color: #f2c14e; }
.speech.mood-proud { border-color: #8be07a; }
.speech b { color: var(--gold2); }
.row { display: flex; gap: 8px; padding: 10px 10px 0; flex-wrap: wrap; }
.row .grow { flex: 1; }
.files { display: flex; flex-wrap: wrap; gap: 6px; padding: 6px 10px 0; }
.files .file { cursor: pointer; font-size: 12.5px; font-weight: 600; padding: 3px 9px; border-radius: 9px; background: #fffaf0;
  color: var(--ink); border: 2px solid var(--ink); max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.files .file:hover { background: #fff3c9; }
.files .more { font-size: 12px; color: var(--soft); align-self: center; }
.banner {
  margin: 8px 10px 0; padding: 6px 10px; border-radius: 10px; font-size: 13px; font-weight: 600;
  background: #5a2234; border: 2px solid #ff7a6e; color: #ffd8d3;
}
/* the gentle "just thinking?" check-in */
.checkin {
  margin: 8px 10px 0; padding: 8px 10px 9px; border-radius: 12px; text-align: center;
  background: #3d3266; border: 2px solid var(--gold2);
}
.checkin .q { font-weight: 700; font-size: 15px; }
.checkin .row { justify-content: center; padding-top: 7px; }

/* big alert layout */
.alert { display: flex; flex-direction: column; align-items: center; text-align: center; padding: 6px 18px 0; }
.alert h1 { margin: 6px 0 2px; font-size: 30px; line-height: 1.1; color: #fff; text-shadow: 0 3px 0 rgba(0,0,0,0.35); }
.alert h1.red { color: #ff8a7a; }
.alert .sub { font-size: 16px; color: var(--soft); max-width: 520px; line-height: 1.3; }
.alert .count {
  margin-top: 8px; font-size: 42px; font-weight: 700; width: 74px; height: 74px; border-radius: 50%;
  display: grid; place-items: center; border: 4px solid var(--paper); color: var(--paper); background: #5a2234;
}
.alert .lostbig { margin-top: 6px; font-size: 18px; font-weight: 700; color: #ff9a8f; }
.alert .actions { display: flex; gap: 10px; flex-wrap: wrap; justify-content: center; margin-top: 12px; }
.alert .choices { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-top: 10px; width: 100%; max-width: 540px; }
.alert .choices .btn { font-size: 15px; padding: 9px 10px; white-space: normal; }
.alert textarea {
  width: 100%; max-width: 520px; height: 60px; margin-top: 10px; border-radius: 12px; border: 3px solid var(--ink);
  padding: 8px 10px; font-size: 15px; resize: none;
}
.alert .note { margin-top: 8px; font-size: 14px; color: var(--soft); }
.alert .ai { margin-top: 6px; font-size: 15px; color: var(--gold2); max-width: 520px; }

.ended { padding: 40px 20px; text-align: center; font-size: 18px; color: var(--soft); }
